using namespace std;

string reverseWords(string s) {
    istringstream iss(s);
    vector<string> words;
    string word;
    while (iss >> word) words.push_back(word);                  // extraction skips all whitespace automatically
    reverse(words.begin(), words.end());
    string result;
    for (int i = 0; i < (int)words.size(); i++) {
        result += words[i];
        if (i + 1 < (int)words.size()) result += ' ';
    }
    return result;
}

