def reverse_words(s):
    chars = list(s.strip())
    n = len(chars)

    def reverse_range(left, right):
        while left < right:
            chars[left], chars[right] = chars[right], chars[left]
            left += 1
            right -= 1

    reverse_range(0, n - 1)                                 # reverse the whole string first

    start = 0
    for i in range(n + 1):
        if i == n or chars[i] == ' ':
            reverse_range(start, i - 1)                          # reverse this one word back to normal
            start = i + 1

    write = 0
    i = 0
    while i < n:
        if chars[i] != ' ':
            if write != 0:
                chars[write] = ' '
                write += 1
            while i < n and chars[i] != ' ':
                chars[write] = chars[i]                              # compact, writing directly over extra spaces
                write += 1
                i += 1
        else:
            i += 1
    return ''.join(chars[:write])


if __name__ == "__main__":
    s = "the sky is blue"
    print(reverse_words(s))

