public class Main {
    String reverseWords(String s) {
        char[] chars = s.trim().toCharArray();
        int n = chars.length;
        reverseRange(chars, 0, n - 1);                             // reverse the whole string first
        int start = 0;
        for (int i = 0; i <= n; i++) {
            if (i == n || chars[i] == ' ') {
                reverseRange(chars, start, i - 1);                       // reverse this one word back to normal
                start = i + 1;
            }
        }
        int write = 0, i = 0;
        while (i < n) {
            if (chars[i] != ' ') {
                if (write != 0) chars[write++] = ' ';
                while (i < n && chars[i] != ' ') {
                    chars[write++] = chars[i++];                            // compact, writing directly over extra spaces
                }
            } else {
                i++;
            }
        }
        return new String(chars, 0, write);
    }

    void reverseRange(char[] chars, int left, int right) {
        while (left < right) {
            char temp = chars[left];
            chars[left] = chars[right];
            chars[right] = temp;
            left++; right--;
        }
    }

    public static void main(String[] args) {
        String s = "the sky is blue";
        Main solution = new Main();
        System.out.println(solution.reverseWords(s));
    }
}

