#include <bits/stdc++.h>
using namespace std;

void reverseRange(string& s, int left, int right) {
    while (left < right) {
        swap(s[left], s[right]);
        left++; right--;
    }
}

string reverseWords(string s) {
    int n = (int)s.size();
    reverseRange(s, 0, n - 1);                                   // reverse the whole string first
    int start = 0;
    for (int i = 0; i <= n; i++) {
        if (i == n || s[i] == ' ') {
            reverseRange(s, start, i - 1);                             // reverse this one word back to normal
            start = i + 1;
        }
    }
    int write = 0, i = 0;
    while (i < n) {
        if (s[i] != ' ') {
            if (write != 0) s[write++] = ' ';
            while (i < n && s[i] != ' ') {
                s[write++] = s[i++];                                       // compact, writing directly over extra spaces
            }
        } else {
            i++;
        }
    }
    s.resize(write);
    return s;
}

